/** Size class of a Turn by its estimated tokens; see notes/buckets.md. */
export type Bucket = "tiny" | "small" | "medium" | "large" | "huge";

/**
 * Exclusive upper bound of each bounded bucket, ascending. A bucket's lower
 * bound is the previous entry's upper bound (inclusive); `huge` is unbounded.
 */
const UPPER_BOUNDS: ReadonlyArray<readonly [Bucket, number]> = [
	["tiny", 350],
	["small", 1800],
	["medium", 7000],
	["large", 24000],
];

export function bucketOf(tokens: number): Bucket {
	for (const [bucket, below] of UPPER_BOUNDS) {
		if (tokens < below) return bucket;
	}
	return "huge";
}

