// suite: TT-5082
import { describe, expect, test } from "bun:test";

import { weighted } from "./budget-table.ts";

describe("weighted", () => {
	test.each([
		[349, 174.5],
		[350, 350],
		[1799, 1799],
		[1800, 2250],
		[6999, 8748.75],
		[7000, 10500],
		[23999, 35998.5],
		[24000, 54000],
	])("weighs %p tokens as %p", (size, expected) => {
		expect(weighted([size])).toEqual([expected]);
	});

	test("keeps the order of the sizes", () => {
		expect(weighted([8000, 120, 2400, 30000, 400])).toEqual([12000, 60, 3000, 67500, 400]);
	});

	test("is empty for no sizes", () => {
		expect(weighted([])).toEqual([]);
	});

	test("rejects a negative size with a RangeError", () => {
		expect(() => weighted([120, -1])).toThrow(RangeError);
	});
});

