import { describe, expect, test } from "bun:test";

import { bucketOf, formatCount, histogram, labelOf, totalOf, turnSizes } from "./budget-table.ts";
import type { HarnessMessage } from "./messages.ts";
import { approximateTokens } from "./tokens.ts";

describe("bucketOf", () => {
	test.each([
		[0, "tiny"],
		[349, "tiny"],
		[350, "small"],
		[1799, "small"],
		[1800, "medium"],
		[6999, "medium"],
		[7000, "large"],
		[23999, "large"],
		[24000, "huge"],
		[Number.MAX_SAFE_INTEGER, "huge"],
	] as const)("%p tokens is %p", (tokens, bucket) => {
		expect(bucketOf(tokens)).toBe(bucket);
	});

	test.each([-1, -0.5, Number.NaN, Number.POSITIVE_INFINITY, Number.NEGATIVE_INFINITY])(
		"rejects %p with a RangeError",
		(tokens) => {
			expect(() => bucketOf(tokens)).toThrow(RangeError);
		},
	);
});

describe("turnSizes", () => {
	const preamble: HarnessMessage = { role: "assistant", content: "ready when you are" };
	const firstPrompt: HarnessMessage = { role: "user", content: "summarise the report" };
	const firstReply: HarnessMessage = { role: "assistant", content: "x".repeat(2000) };
	const secondPrompt: HarnessMessage = { role: "user", content: "thanks" };
	const secondReply: HarnessMessage = { role: "assistant", content: "done" };

	test("sizes each prompted Turn in order and drops the leading Turn with no prompt", () => {
		expect(turnSizes([preamble, firstPrompt, firstReply, secondPrompt, secondReply])).toEqual([
			approximateTokens([firstPrompt, firstReply]),
			approximateTokens([secondPrompt, secondReply]),
		]);
	});

	test("keeps a Turn whose user prompt has empty text", () => {
		const emptyPrompt: HarnessMessage = { role: "user", content: "" };
		expect(turnSizes([emptyPrompt, firstReply])).toEqual([approximateTokens([emptyPrompt, firstReply])]);
	});
});

describe("histogram", () => {
	test("counts the sample sizes per bucket, largest bucket first", () => {
		expect(histogram([120, 90, 2400, 400, 8000])).toEqual([
			{ bucket: "large", count: 1 },
			{ bucket: "medium", count: 1 },
			{ bucket: "small", count: 1 },
			{ bucket: "tiny", count: 2 },
		]);
	});

	test("keeps empty buckets below huge at zero and leaves out an empty huge", () => {
		expect(histogram([23999, 7000, 349])).toEqual([
			{ bucket: "large", count: 2 },
			{ bucket: "medium", count: 0 },
			{ bucket: "small", count: 0 },
			{ bucket: "tiny", count: 1 },
		]);
	});

	test("gives every bucket but huge a zero count for no sizes", () => {
		expect(histogram([])).toEqual([
			{ bucket: "large", count: 0 },
			{ bucket: "medium", count: 0 },
			{ bucket: "small", count: 0 },
			{ bucket: "tiny", count: 0 },
		]);
	});
});

describe("totalOf", () => {
	test("sums the sizes unweighted", () => {
		expect(totalOf([120, 90, 2400, 400, 8000])).toBe(11010);
	});

	test("is 0 for no sizes", () => {
		expect(totalOf([])).toBe(0);
	});
});

describe("formatCount", () => {
	test.each([
		[0, "0"],
		[740, "740"],
		[999, "999"],
		[1000, "1.0k"],
		[1234, "1.2k"],
		[1250, "1.3k"],
		[12000, "12.0k"],
	])("shows %p as %p", (n, shown) => {
		expect(formatCount(n)).toBe(shown);
	});

	// Halves that binary cannot hold exactly, which toFixed would round down.
	test.each([
		[1450, "1.5k"],
		[1950, "2.0k"],
		[9950, "10.0k"],
	])("rounds the half %p up, as %p", (n, shown) => {
		expect(formatCount(n)).toBe(shown);
	});
});

describe("labelOf", () => {
	test.each([
		["tiny", "crumbs"],
		["small", "bites"],
		["medium", "meals"],
		["large", "feasts"],
		["huge", "banquets"],
	] as const)("labels %p as %p", (bucket, label) => {
		expect(labelOf(bucket)).toBe(label);
	});
});

