import type { HarnessMessage } from "./messages.ts";
import { approximateTokens } from "./tokens.ts";
import { reconstructTurns } from "./turns.ts";

/** Turn-size buckets from smallest to largest; see notes/buckets.md. */
export const BUCKETS = ["tiny", "small", "medium", "large", "huge"] as const;

/** Size class of a Turn by its estimated tokens. */
export type Bucket = (typeof BUCKETS)[number];

/**
 * Inclusive lower bound of each bucket. A bucket's exclusive upper bound is
 * the next bucket's lower bound; the largest bucket is unbounded.
 */
const FROM: Record<Bucket, number> = {
	tiny: 0,
	small: 350,
	medium: 1800,
	large: 7000,
	huge: 24000,
};

/**
 * The bucket a Turn of `tokens` estimated tokens falls in.
 *
 * @throws RangeError when `tokens` is negative or not finite.
 */
export function bucketOf(tokens: number): Bucket {
	if (!Number.isFinite(tokens) || tokens < 0) {
		throw new RangeError(`Turn size must be a finite, non-negative token count: ${tokens}`);
	}
	let bucket: Bucket = BUCKETS[0];
	for (const candidate of BUCKETS) {
		if (tokens >= FROM[candidate]) bucket = candidate;
	}
	return bucket;
}

/**
 * The estimated tokens of each Turn in `messages`, in Conversation order.
 *
 * Messages before the first user prompt (a system prompt, say) form a leading
 * Turn with no prompt; it answers no prompt, so it is dropped rather than
 * counted. That Turn is recognised by its first message not being a user
 * message, not by its empty `prompt`: a user prompt with empty text is a real
 * Turn and is kept.
 */
export function turnSizes(messages: HarnessMessage[]): number[] {
	const turns = reconstructTurns(messages);
	const counted = turns[0]?.messages[0]?.role === "user" ? turns : turns.slice(1);
	return counted.map((turn) => approximateTokens(turn.messages));
}

/**
 * How many of `sizes` fall in each bucket, from the largest bucket to the
 * smallest. Every bucket has an entry, an empty one with count 0, except
 * `huge`, which is left out when no size falls in it.
 *
 * @throws RangeError when a size is negative or not finite.
 */
export function histogram(sizes: number[]): { bucket: Bucket; count: number }[] {
	const counts: Record<Bucket, number> = { tiny: 0, small: 0, medium: 0, large: 0, huge: 0 };
	for (const size of sizes) counts[bucketOf(size)]++;
	return [...BUCKETS]
		.reverse()
		.filter((bucket) => bucket !== "huge" || counts.huge > 0)
		.map((bucket) => ({ bucket, count: counts[bucket] }));
}

/** The plain, unweighted sum of `sizes`; 0 for none. */
export function totalOf(sizes: number[]): number {
	let total = 0;
	for (const size of sizes) total += size;
	return total;
}

/** What a Turn's size is multiplied by in its bucket; see notes/weights.md. */
const WEIGHT: Record<Bucket, number> = {
	tiny: 0.5,
	small: 1,
	medium: 1.25,
	large: 1.5,
	huge: 2.25,
};

/**
 * A size of `bucket` times that bucket's weight, rounded to the nearest
 * multiple of 10 with halves rounding up (see notes/rounding.md).
 */
function weightedSize(size: number, bucket: Bucket): number {
	// Math.round takes halves up, and sizes are never negative.
	return Math.round((size * WEIGHT[bucket]) / 10) * 10;
}

/**
 * Each of `sizes` times the weight of its bucket, in the same order, rounded
 * to the nearest multiple of 10 with halves rounding up.
 *
 * @throws RangeError when a size is negative or not finite.
 */
export function weighted(sizes: number[]): number[] {
	return sizes.map((size) => weightedSize(size, bucketOf(size)));
}

/**
 * The sum of the weighted sizes in each bucket, each size rounded before it is
 * added. Every bucket has an entry, 0 when no size falls in it.
 *
 * @throws RangeError when a size is negative or not finite.
 */
export function bucketTotals(sizes: number[]): Map<Bucket, number> {
	const totals = new Map<Bucket, number>(BUCKETS.map((bucket) => [bucket, 0]));
	for (const size of sizes) {
		const bucket = bucketOf(size);
		totals.set(bucket, (totals.get(bucket) ?? 0) + weightedSize(size, bucket));
	}
	return totals;
}

/**
 * `n` as a rendered table shows it (see notes/rounding.md): below 1000 as is,
 * otherwise in thousands with exactly one decimal and a `k` suffix, halves
 * rounding up, so 1250 is `1.3k`.
 */
export function formatCount(n: number): string {
	if (n < 1000) return String(n);
	// Rounded in whole hundreds rather than with toFixed, which misrounds
	// halves that binary cannot hold exactly: 1450 / 1000 is 1.4499…, so
	// toFixed(1) gives 1.4.
	const tenths = Math.round(n / 100);
	return `${Math.floor(tenths / 10)}.${tenths % 10}k`;
}

/** The row label of each bucket in a rendered table; see notes/legend.md. */
const LABEL: Record<Bucket, string> = {
	tiny: "crumbs",
	small: "bites",
	medium: "meals",
	large: "feasts",
	huge: "banquets",
};

export function labelOf(bucket: Bucket): string {
	return LABEL[bucket];
}

/** A Turn larger than this many tokens counts towards the summary's `over`. */
const OVER_TOKENS = 9000;

/**
 * The one-line summary of `sizes` against `budget` (see notes/format.md):
