import { bucketTotals, formatCount, histogram, labelOf } from "./budget-table.ts";

/**
 * The bucket table as rows, laid out as notes/legend.md gives: a header, then
 * one row per histogram entry in histogram order, columns joined by ` | `
 * with no padding.
 *
