	test("renders zero rows for every bucket but huge when there are no sizes", () => {
		expect(renderTable([])).toEqual([
			"bucket | turns | weighted",
			"feasts | 0 | 0",
			"meals | 0 | 0",
			"bites | 0 | 0",
			"crumbs | 0 | 0",
		]);
	});
});

describe("summaryLine", () => {
	test("lays out the example from notes/format.md", () => {
		expect(summaryLine([400, 1000, 8000], 20000)).toBe(
			"turns=3 · total=9400 · used=47% · peak=large · over=0",
		);
	});

	test("reports peak=none and zeros for no Turns", () => {
		expect(summaryLine([], 20000)).toBe("turns=0 · total=0 · used=0% · peak=none · over=0");
	});

	test("counts only Turns strictly over 9000 tokens and lets used exceed 100%", () => {
		expect(summaryLine([9000, 9001, 30000, 5], 10000)).toBe(
			"turns=4 · total=48006 · used=480% · peak=huge · over=2",
		);
	});

	test("rounds used down to a whole percentage", () => {
		expect(summaryLine([29], 100)).toBe("turns=1 · total=29 · used=29% · peak=tiny · over=0");
		expect(summaryLine([199], 300)).toBe("turns=1 · total=199 · used=66% · peak=tiny · over=0");
	});

	test.each([0, -100, Number.NaN, Number.POSITIVE_INFINITY])("rejects a budget of %p with a RangeError", (budget) => {
		expect(() => summaryLine([400], budget)).toThrow(RangeError);
	});

	test("rejects a negative size with a RangeError", () => {
		expect(() => summaryLine([400, -1], 20000)).toThrow(RangeError);
	});
});
